    if start == goal:
        return [start]
    rows, cols = (len(grid), len(grid[0]))
    heuristic = lambda h, g: abs(h - goal[0]) + abs(g - goal[1])
    total_move_costs = [(row, col, float('inf')) for row in range(rows) for col in range(cols)]
    predecessors = {(row, col): None for row in range(rows) for col in range(cols)}
    H, G = start
    area = [(H, G, heuristic(H, G))]
    while area:
        H, G, dist_diff = min(area, key=lambda h_g_dist: h_g_dist[2])
        area.remove((H, G, dist_diff))
        for neighbor in [(H - 1, G), (H + 1, G), (H, G - 1), (H, G + 1)]:
            if 0 <= neighbor[0] < rows and 0 <= neighbor[1] < cols:
