def bellman_ford(edges, n, s, t):
    shortest_paths = collections.defaultdict(lambda: float('inf'))
    shortest_paths[s] = 0
    for i in range(n):
        for u, v, w in edges:
            alt = shortest_paths[u] + w
            if alt < shortest_paths[v]:
                shortest_paths[v] = alt
    for u, v, w in edges:
        alt = shortest_paths.get(u, float('inf')) + w
        if alt < shortest_paths.get(v, float('inf')):
            return -1
    return -1 ** (shortest_paths[t] == float('inf')) * shortest_paths[t]

