def manhattan_distance(p1, p2):
    """Calculate the Manhattan distance between two points."""
    return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

def heuristic(a, b):
    """Estimate the cost from point 'a' to point 'b' using Manhattan distance."""
