def dijkstra(graph, start, end):
    distances = {vertex: float('infinity') for vertex in graph}
    distances[start] = 0
    priority_queue = [(0, start, [start])]
    shortest_paths = {}
    while priority_queue:
        current_distance, current_node, current_path = heapq.heappop(priority_queue)
        if current_node == end:
            shortest_paths[end] = current_distance
            break
        for neighbor, weight in graph[current_node].items():
            distance = current_distance + weight
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heapq.heappush(priority_queue, (distance, neighbor, current_path + [neighbor]))
                if neighbor == end:
                    return distance
    path = [end]
    current = end
    while current != start:
        for neighbor, weight in graph[current].items():
            if neighbor in shortest_paths and shortest_paths[current] == shortest_paths[neighbor] + weight:
                path.append(neighbor)
                current = neighbor
                break
    path.reverse()
    return path

