def solve(grid: list[str], start: tuple[int, int], goal: tuple[int, int]) -> list[tuple[int, int]]:
    """
    Solution BFS.

    Time complexity: $O(	ext{num cells})$
    Space complexity: $O(	ext{num cells})$
    """
    Q: list[tuple[int, int]] = [start]
    came_from: dict[int, tuple[int, int]] = {}
    while len(Q) != 0:
        i, j = Q.pop()
        for delta in (-1, 1):
            if j + delta < len(grid[0]) and grid[i][j + delta] != '#':
                if grid[i][j + delta] == '.' and (i, j + delta) not in came_from:
                    Q.append((i, j + delta))
                    came_from[i, j + delta] = (i, j)
            if i + delta < len(grid) and grid[i + delta][j] != '#':
                if grid[i + delta][j] == '.' and (i + delta, j) not in came_from:
                    Q.append((i + delta, j))
                    came_from[i + delta, j] = (i, j)
    path: list[tuple[int, int]] = []
    focus = goal
    while focus != start:
        path.append(focus)
        focus = came_from[focus]
    path.append(start)
    path.reverse()
    return path

