def check_deadlock(path: list[tuple[int, int]], grid: list[str]) -> bool:
    if len(path) < 3:
        return False
    board = get_board(grid, path)
    if not has_only_one_way(board, path, False):
        return True
    i, j = (path[-1][0], path[-1][1])
    matrix = board[i][j]
    if matrix == 0:
        return True
    if i == 0:
        if get_robot_from_monsters(i, j, matrix, board) == 0:
            return True
    if j == 0:
        if get_robot_from_monsters(i, j, matrix, board) == 0:
            return True
    if i == len(board) - 1:
        if get_robot_from_monsters(i - 1 == 0 and j == 0, j - 1 == 0 and j == 0, matrix, board) == 0:
            return True
    if j == len(board[0]) - 1:
        if get_robot_from_monsters(i, j - 1, matrix, board) == 0:
