                return True
        return False
    visited = set()
    neighbors = lambda row: [(row[0] + 1, row[1]), (row[0] - 1, row[1]), (row[0], row[1] + 1), (row[0], row[1] - 1)]

    def in_bounds(node: tuple[int, int]) -> bool:
        return 0 <= node[0] < len(grid) and 0 <= node[1] < len(grid[0]) and (grid[node[0]][node[1]] == '.')
    iddfs(None, [])
    return self.solution

def solve(grid: list[str], start: tuple[int, int], goal: tuple[int, int]) -> list[tuple[int, int]]:
    """Given a grid with # = wall and . = free space, and a start and goal location, recursively find a path from start to goal. If there is no path, return an empty list. If there are multiple paths, any one is acceptable."""

    def explore(start: tuple[int, int], goal: tuple[int, int], explored: dict[tuple[int, int], list[tuple[int, int]]]={}, directions: list[str]=['>', '<', 'v', '^'], path: list[tuple[int, int]]=[]) -> list[tuple[int, int]]:
        if start == goal:
            return path + [start]
        if start in explored:
            return explored[start]
        r, c = start
        areas = ['>', '<', 'v', '^']
        if r > 0:
            areas[areas.index('^')] = '.'
        if r < len(grid) - 1:
            areas[areas.index('v')] = '.'
        if c > 0:
            areas[areas.index('>')] = '.'
        if c < len(grid[0]) - 1:
            areas[areas.index('<')] = '.'
        explored[start] = []
        for area in areas:
            if area == '.':
                continue
            if area == '>':
                adj = (r, c + 1)
            elif area == '<':
                adj = (r, c - 1)
            elif area == 'v':
                adj = (r + 1, c)
            else:
                adj = (r - 1, c)
            explored[start] += explore(adj, goal, explored, areas[:areas.index(area)] + areas[areas.index(area) + 1:], path + [start])
        return explored[start]
    base = explore(start, goal)
    if base == []:
        return []
    return base + [goal]

def solve(grid: list[str], start: tuple[int, int], goal: tuple[int, int]) -> list[tuple[int, int]]:
    width = len(grid[0])
    start_row, start_col = start
    goal_row, goal_col = goal
    visited = {(start_row, start_col)}
    paths: list[tuple[list[tuple[int, int]], int]] = [([], 0)]
    while paths:
        path, distance = paths.pop(0)
        path, distance = min(paths, key=lambda x: x[1])
        if path and path[-1] == (goal_row, goal_col):
            return path
        for drow, dcol in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            row, col = path[-1]
            new_row = row + drow
            new_col = col + dcol
            if 0 <= new_row < len(grid) and 0 <= new_col < width and ((new_row, new_col) not in visited) and (grid[new_row][new_col] != '#'):
                visited.add((new_row, new_col))
                paths.append((path + [(new_row, new_col)], distance + 1))
    return []

def solve(grid: list[str], start: tuple[int, int], goal: tuple[int, int]) -> list[tuple[int, int]]:
    """
    A Depth-First-Search algorithm for 2d spaces.
    """
    frontier = [start]
    prev = {}
    while frontier:
        next_frontier = []
        for node in frontier:
            y, x = node
            for y_offset, x_offset in ((0, -1), (0, 1), (-1, 0), (1, 0)):
                try:
                    y2, x2 = (y + y_offset, x + x_offset)
                    if (y2, x2) in prev:
                        continue
                except IndexError:
                    continue
                else:
                    item = grid[y2][x2]
                    if item == 'g':
                        prev[y2, x2] = node
                        next_frontier.append((y2, x2))
                    elif item == '.':
                        prev[y2, x2] = node
                        next_frontier.append((y2, x2))
                    elif item == 'e':
                        prev[y2, x2] = node
                        return backtrack(last=(y2, x2), prev=prev)
        frontier = next_frontier
    return

def crawl(grid: list[str], start: tuple[int, int], goal: tuple[int, int]) -> list[tuple[int, int]]:
    """
    A Breadth-First-Search algorithm for 2d spaces.
    """
    frontier = {start}
    prev = {start}
    while frontier:
        node = frontier.pop()
        y, x = node
        new_rows = [row for row in grid]
        item = grid[y][x]
        if item == 'e':
            return backtrack(last=node, prev=prev)
        elif item == '.':
            pass
        else:
            continue
        for y_offset, x_offset in ((0, -1), (0, 1), (-1, 0), (1, 0)):
            try:
                y2, x2 = (y + y_offset, x + x_offset)
            except IndexError:
                continue
            else:
                item = grid[y2][x2]
                if item == '.':
                    if (y2, x2) not in prev:
                        new_rows[y2] = new_rows[y2][:x2] + '*' + new_rows[y2][x2 + 1:]
                        prev[y2, x2] = node
                        frontier.add((y2, x2))
        grid[y] = [char for character in new_rows[y]]
        grid[y][x] = '*'
    return

def backtrack(last: tuple[int, int], prev: dict[tuple[int, int], int]) -> list[tuple[int, int]]:
    """
    Traverses a prev dictionary to get the path taken by the depth-search algorithm.
    """
    nodes = [last]
    while nodes[-1] != list(prev)[0]:
        nodes.append(prev[nodes[-1]])
    nodes.reverse()
    return nodes

def solve(grid: list[str], start: tuple[int, int], goal: tuple[int, int]) -> list[tuple[int, int]]:
    goal_col, goal_row = goal
    start_col, start_row = start
    s_gridwidth = len(grid[0])
    s_gridtheight = len(grid)
    s_coords = {(col, row) for col in range(s_gridwidth) for row in range(s_gridtheight)}
    s_move = {-1, 1}

    def manhattendistance(current: tuple[int, int], goal: tuple[int, int]) -> int:
        return abs(current[0] - goal[0]) + abs(current[1] - goal[1])

    def boundarycurrent(current: tuple[int, int]) -> int:
        boundaries = (current[0] == 0, current[0] == s_gridwidth - 1, current[0] == grid[s_gridtheight - 1].index('#'), current[0] == goal[0] and (goal_col == current[1] - 1 or goal_col == current[1] or goal_col == current[1] + 1) and (current[1] < goal[1]))
        return any(boundaries)

    def iswalled(current: tuple[int, int]) -> int:
        gridcontent = (grid[goal_row][goal_col], grid[goal_row][goal_col + 1], grid[goal_row][goal_col - 1])
        if manhattendistance(current, (current[0], goal[1] - 1)) == 1:
            return grid[goal_row][goal_col - 1] == '#'
        elif manhattendistance(current, (current[0], goal[1] + 1)) == 1:
            return grid[goal_row][goal_col + 1] == '#'
        elif manhattendistance(current, (current[0] - 1, goal[1])) == 1 or manhattendistance(current, (current[0] + 1, goal[1])) == 1:
            gridcontent = (grid[goal_row - 1][goal_col], grid[goal_row + 1][goal_col], grid[goal_row][goal_col - 1], grid[goal_row][goal_col + 1])
            return current[0] == goal[0] and any([gridcontent[i] == '#' for i in s_move])

    def isgoal(current: tuple[int, int]) -> int:
        if manhattendistance(current, goal) == 1:
            return grid[goal_row][goal_col] != '#'
        elif manhattendistance(current, (goal[0], goal[1] - 1)) == 1:
            return grid[goal_row][goal_col - 1] != '#'
        elif manhattendistance(current, (goal[0], goal[1] + 1)) == 1:
            return grid[goal_row][goal_col + 1] != '#'
        elif manhattendistance(current, (goal[0] - 1, goal[1])) == 1:
            return grid[goal_row - 1][goal_col] != '#'
        elif manhattendistance(current, (goal[0] + 1, goal[1])) == 1:
            return grid[goal_row + 1][goal_col] != '#'
        return False

    def step(arg: tuple) -> list[tuple]:
        """UP, DOWN, LEFT, RIGHT"""
        state, current = arg
        if state == 0:
            return [(current[0] - 1, current[1])] if (current[0], current[1] - 1) not in s_coords or boundarycurrent(current) or iswalled(current) == 1 else [(current[0] - 1, current[1]), (current[0], current[1] - 1)]
        elif state == 1:
            return [(current[0] + 1, current[1])] if (current[0], current[1] - 1) not in s_coords or boundarycurrent(current) or iswalled(current) == 1 else [(current[0] + 1, current[1]), (current[0], current[1] - 1)]
        if state == 2:
            return [(current[0], current[1] - 1)] if (current[0], current[1] + 1) not in s_coords or boundarycurrent(current) or iswalled(current) == 1 else [(current[0], current[1] - 1), (current[0], current[1] + 1)]

def solve(grid: list[str], start: tuple[int, int], goal: tuple[int, int]) -> list[tuple[int, int]]:
    width = len(grid[0])
    height = len(grid)
    grid = [list(row) for row in grid]
    grid[start[0]][start[1]] = '#'
    grid[goal[0]][goal[1]] = '#'
    queue = [(start[0], start[1])]
    while queue:
        cell = queue.pop(0)
        if cell == goal:
            break
        for dr in [0, 1]:
            for dc in [0, 1]:
                r = cell[0] + dr
                c = cell[1] + dc
                if 0 <= r < height and 0 <= c < width and (grid[r][c] != '#') and ((r, c) not in queue):
                    queue.append((r, c))
                    grid[r][c] = '#'
    path = [goal]
    while path[-1] != start:
        r, c = path[-1]
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if abs(dr) == abs(dc) or dr == dc == 0 or dr == 0 == dc:
                    continue
                nr = r + dr
                nc = c + dc
                if (nr, nc) in path:
                    continue
                if grid[nr][nc] == '#':
                    path.append((nr, nc))
                    break
    path.reverse()
    return path

def solve(grid: list[str], start: tuple[int, int], goal: tuple[int, int]) -> list[tuple[int, int]]:
    """
    Solve the maze using BFS.
    """
    queue = [([start], {start})]
    while queue:
        path, visited = queue.pop(0)
        if not len(path) == 1 or path[-1] == goal:
            for i, path in route(grid, path, visited):
                if grid[goal[0]][goal[1]] == '.':
                    queue.append([i[:-1], i])
                if not len(i) == len(path):
                    queue.append([i, i[:-1]])
            visited.update(i)
        if path and grid[path[-1][0]][path[-1][1]] == '.':
            queue.append([path, visited])
        elif path:
            queue.append([i + path[-1:], i])
    return []

def route(grid: list[str], path: list[tuple[int, int]], visited: set[tuple[int, int]]) -> list[tuple[tuple[int, int], set[tuple[int, int]]]]:
    """
    Given a path, find all paths to the goal that use the last cell in the path.
    """
    row, col = path[-1]
    if col > 0 and grid[row][col - 1] == '.' and ((row, col - 1) not in visited):
        yield (path + [(row, col - 1)], {*visited - {(row, col)}, (row, col - 1)})
    if col < len(grid[0]) - 1 and grid[row][col + 1] == '.' and ((row, col + 1) not in visited):
        yield (path + [(row, col + 1)], {*visited - {(row, col)}, (row, col + 1)})
    if row > 0 and grid[row - 1][col] == '.' and ((row - 1, col) not in visited):
        yield (path + [(row - 1, col)], {*visited - {(row, col)}, (row - 1, col)})
    if row < len(grid) - 1 and grid[row + 1][col] == '.' and ((row + 1, col) not in visited):
        yield (path + [(row + 1, col)], {*visited - {(row, col)}, (row + 1, col)})

def solve(grid: list[str], start: tuple[int, int], goal: tuple[int, int]) -> list[tuple[int, int]]:

    def path(board, end) -> list[tuple[int, int]]:
        path = []
        while end != (1, 1):
            path.insert(0, end)
            end = board[end]
        path.insert(0, (1, 1))
        return path

    def finder(grid):
        c_grid = [*map(list, grid)]
        size_y, size_x = (len(grid), len(grid[0]))
        y, x = start
        obj_row, obj_col = goal
        c_grid[y][x] = 0
        board = {}
        path = [(y, x)]
        if y == obj_row and x == obj_col:
            return [(y, x)]
        while path:
            y, x = y, x = path.pop()
            for m_y, m_x in ((1, 0), (0, -1), (-1, 0), (0, 1)):
                m_y, m_x = (y + m_y, x + m_x)
                if 1 <= m_y <= size_y and 1 <= m_x <= size_x and (c_grid[m_y - 1][m_x - 1] == '.'):
                    c_grid[m_y - 1][m_x - 1] = range(0, board.get((y, x), 0) + 2)[1]
                    board[m_y, m_x] = (y, x)
                    path.append((m_y, m_x))
        return path(board, (obj_row, obj_col))
    try:
        return finder(grid)
    except TypeError:
        return []

def solve(grid: list[str], start: tuple[int, int], goal: tuple[int, int]) -> list[tuple[int, int]]:
    """ DFS - no circular closure.

	Tuple of coordinates is a node.

	DFS is good here because:
	- recursive stacks are small (30^2 = 900)
	- it fits the fold/unfold pattern
	"""
    good: list[tuple[int, int]] = []
    walk_coefs: list[dict] = [dict(l=-1, j=0), dict(l=1, j=0), dict(l=0, j=-1), dict(l=0, j=1)]
    walk: dict[tuple[int, int]] = dict()

    def walk_to(parent_cell: tuple[int, int] | None, goal_cell: tuple[int, int], canVisit) -> bool:
        row, column = parent_cell
        marked_cells: list[tuple[int, int]] = []
        for coef in walk_coefs:
            neighbour_row: int = row + coef['l']
            neighbour_column: int = column + coef['j']
            neighbour_cell: tuple[int, int] = (neighbour_row, neighbour_column)
            if 0 <= neighbour_row < len(grid):
                if 0 <= neighbour_column < len(grid[0]):
                    if canVisit(neighbour_cell):
                        marked_cells.append(neighbour_cell)
            try:
                walk[neighbour_cell]
            except:
                walk[neighbour_cell] = walk[parent_cell] + 1
        if len(marked_cells) == 0:
            return False
        if goal_cell == parent_cell:
            good.extend(reversed(get_path_to_root(None)))
            return True
        else:
            for walk_cell in marked_cells:
                walk_to(walk_cell, goal_cell, canVisit)
        return False

    def canVisit(cell: tuple[int, int]) -> bool:
        if 0 > cell[0] or 0 > cell[1] or cell[0] > len(grid) - 1 or (cell[1] > len(grid[0]) - 1) or (grid[cell[0]][cell[1]] == '#'):
            return False
        if cell in walk:
            return False
        return True

    def get_path_to_root(current: tuple[int, int] | None) -> list[tuple[int, int]]:
        path: list[tuple[int, int]] = []
        while current:
            path.append(current)
            current = walk.get(current)
        return path
    walk[start] = 0
    walk_to(start, goal, canVisit)
    return good

