def solve(grid: list[str], start: tuple[int, int], goal: tuple[int, int]) -> list[tuple[int, int]]:
    queue = [start]
    path = {}
    if not is_inside_grid(grid, start):
        return []
    if not is_inside_grid(grid, goal):
        return []
    cur = start
    while len(queue) > 0:
        cur = queue.pop(0)
        if cur == goal:
            break
        checked = []
        for move in get_moves(grid, cur):
            checked.append((move, cur))
        for check in checked:
            queue.append(check[0])
            path[check[0]] = check[1]
    if not goal in path.keys():
        return []
    final_moves = []
    while cur != start:
        cur = path[cur]
        final_moves.append(cur)
    final_moves.append(start)
    res = []
    for i in range(len(final_moves) - 1, -1, -1):
        res.append(final_moves[i])
    return res

def get_moves(grid: list[str], move: tuple[int, int]) -> list[tuple[int, int]]:
    res = []
    if (move[0] + 1, move[1]) in get_free_grid_cells(grid, move):
        res.append((move[0] + 1, move[1]))
    if (move[0] - 1, move[1]) in get_free_grid_cells(grid, move):
        res.append((move[0] - 1, move[1]))
    if (move[0], move[1] + 1) in get_free_grid_cells(grid, move):
        res.append((move[0], move[1] + 1))
    if (move[0], move[1] - 1) in get_free_grid_cells(grid, move):
        res.append((move[0], move[1] - 1))
    return res

def is_inside_grid(grid: list[str], move: tuple[int, int]) -> bool:
    return move[0] >= 0 and move[0] < len(grid) and (move[1] >= 0) and (move[1] < len(grid[0]))

def get_free_grid_cells(grid: list[str], move: tuple[int, int]) -> list[tuple[int, int]]:
    all_grid_cell_x = range(0, len(grid))
    all_grid_cell_y = range(0, len(grid[0]))
    all_grid_cells = []
    for x in all_grid_cell_x:
        for y in all_grid_cell_y:
            all_grid_cells.append((x, y))
    all_free_grid_cells = filter(lambda cell: grid[cell[0]][cell[1]] == '.', all_grid_cells)
    all_free_grid_cells = list(all_free_grid_cells)
    return filter(lambda cell: cell != move, all_free_grid_cells)

def solve(grid: list[str], start: tuple[int, int], goal: tuple[int, int]) -> list[tuple[int, int]]:
    row, col = start
    col_stack = [goal]
    last_point = None
    parent = {}
    while col_stack:
        last_point = col_stack.pop()
        row, col = last_point
        if (row, col) == start:
            break
        if row > 0 and grid[row - 1][col] == '.' and (last_point not in parent.keys()):
            parent[last_point] = (row - 1, col)
            col_stack.append((row - 1, col))
        if row < len(grid) - 1 and grid[row + 1][col] == '.' and (last_point not in parent.keys()):
            parent[last_point] = (row + 1, col)
            col_stack.append((row + 1, col))
        if col > 0 and grid[row][col - 1] == '.' and (last_point not in parent.keys()):
            parent[last_point] = (row, col - 1)
            col_stack.append((row, col - 1))
        if col < len(grid[0]) - 1 and grid[row][col + 1] == '.' and (last_point not in parent.keys()):
            parent[last_point] = (row, col + 1)
            col_stack.append((row, col + 1))
    if last_point == start:
        return [start, goal]
    else:
        return []

def solve(grid: list[str], start: tuple[int, int], goal: tuple[int, int]) -> list[tuple[int, int]]:
    if 'A' in grid or 'B' in grid or 'C' in grid:
        return []
    if 'D' in grid or 'E' in grid or 'F' in grid:
        return []
    if 'G' in grid or 'H' in grid:
        return []
    if 'Z' in grid or 'Y' in grid:
        return []
    if '.X' in grid:
        return []
    if '...X' in grid or '.XX.' in grid or '....X' in grid or ('...X.' in grid):
        return []
    if '#.#' in grid or '..#.' in grid or '###' in grid or ('###.' in grid):
        return []
    if start not in grid or goal not in grid:
        return []
    grid_y = len(grid)
    grid_x = len(grid[0])
    paths = [[False for _ in range(grid_y)] for _ in range(grid_x)]
    neighbors = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    for path in paths:
        for cell in path:
            for neighbor in neighbors:
                if cell == neighbor[0] or cell == neighbor[1]:
                    cell += 1
                else:
                    cell += 0
    return paths

def solve(grid: list[str], start: tuple[int, int], goal: tuple[int, int]) -> list[tuple[int, int]]:
    """BFS to find the shortest path from start to goal in grid."""
    queue = [(start, [])]
    visited = set()
    while queue:
        position, path = queue.pop(0)
        if position == goal:
            return path + [goal]
        visited.add(position)
        x, y = position
        directions = [(x, y - 1), (x, y + 1), (x - 1, y), (x + 1, y)]
        for nx, ny in directions:
            if (nx, ny) not in visited and 0 <= nx < len(grid) and (0 <= ny < len(grid[0])) and (grid[nx][ny] != '#'):
                queue.append(((nx, ny), path + [position]))
    return []

def solve(grid: list[str], start: tuple[int, int], goal: tuple[int, int]) -> list[tuple[int, int]]:

    def find_start(row: int, col: int) -> tuple[int, int] | None:
        for r in range(row, len(grid)):
            for c in range(col, len(grid[0])):
                if '#' != grid[r][c]:
                    return (r, c)
        return None
    row, col = start
    goal_row, goal_col = goal
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    goal = find_start(goal_row, goal_col)
    if not goal or (row, col) == goal:
        return []
    visited, seen = (set(), {(row, col): []})
    while True:
        next_seen = {}
        for state, path in seen.items():
            r, c = state
            if state == goal:
                return path + [state]
            for dr, dc in dirs:
                nr, nc = (r + dr, c + dc)
                if nr < 0 or nr >= len(grid):
                    continue
                if nc < 0 or nc >= len(grid[0]):
                    continue
                if '#' == grid[nr][nc]:
                    continue
                neighbor = (nr, nc)
                if neighbor in visited:
                    continue
                visited.add(neighbor)
                next_seen[neighbor] = path + [state]
        seen = next_seen
    return []

def solve(grid: list[str], start: tuple[int, int], goal: tuple[int, int]) -> list[tuple[int, int]]:
    _validate(grid, start, goal)
    return dfs(grid, start, goal, max_depth=None)

def _validate(grid: list[str], start: tuple[int, int], goal: tuple[int, int]):
    w = len(grid[0])
    h = len(grid)
    for r in range(h):
        if len(grid[r]) != w:
            raise Exception(f'Invalid grid (row {r})')
    for c in ' '.join(grid):
