    def is_in_board(r: int, c: int, n: int, m: int) -> bool:
        return r >= 0 and c >= 0 and (r < n) and (c < m)

    def is_free(grid: list[str], r: int, c: int) -> bool:
        return grid[r][c] == '.'

    def swap(tuples):
        return (tuples[1], tuples[0])
    from_data = [-1 for _ in range(n * m)]
    from_data[swap(start)] = -1
    queue = [swap(start)]
    grid[start[0]] = grid[start[0]][:start[1]] + '|' + grid[start[0]][start[1] + 1:]
    while queue:
        u = queue.pop(0)
