        c = u[1]
        for dr, dc in directions:
            r_n = r + dr
            c_n = c + dc
            if is_in_board(r_n, c_n, n, m) and is_free(grid, r_n, c_n):
                from_data[swap((r_n, c_n))] = swap((r, c))
                queue.append(swap((r_n, c_n)))
                if r_n == goal[0] and c_n == goal[1]:
                    grid[r_n] = grid[r_n][:c_n] + '#' + grid[r_n][c_n + 1:]
