def solve(grid: list[str], start: tuple[int, int], goal: tuple[int, int]) -> list[tuple[int, int]]:
    """Solves the grid helper function that runs depth first search"""

    def dfs(i: int, j: int, current_path: list[tuple[int, int]]) -> bool:
        """Runs the depth first search"""
        if not (0 <= i < len(grid) and 0 <= j < len(grid[0])) or (i, j) in current_path or grid[i][j] == '#':
            return False
        current_path.append((i, j))
        if (i, j) == goal:
            return True
        if dfs(i + 1, j, current_path.copy()):
            return True
        if dfs(i - 1, j, current_path.copy()):
            return True
        if dfs(i, j + 1, current_path.copy()):
            return True
        if dfs(i, j - 1, current_path.copy()):
            return True
        return False
    current_path = []
    dfs(start[0], start[1], current_path)
    return current_path if current_path else []

def solve(grid: list[str], start: tuple[int, int], goal: tuple[int, int]) -> list[tuple[int, int]]:
    """Return a valid path from start to goal through grid, or an empty list if the goal is unreachable."""
    start_len = len(grid[0])
    start = (start[0], start[1] - 1)
    goal = (goal[0], goal[1] - 1)
    for row, line in enumerate(grid):
        if len(line) != start_len:
            raise ValueError(f'Row {row + 1} has a different length than the first and last rows.')
    stack = [(start, 1, -1, -1, [])]
    done = {start}
    while stack:
        position, length, dir, prev_dir, path = stack.pop()
        row, col = position
        if length == 3 and prev_dir >= 0:
            continue
        elif position == goal:
            return path + [pos_to_coord(col + 1)]
        elif length <= 2 and dir != prev_dir:
            new_length, rem = divmod(abs(dir - prev_dir), 2)
            for bump in range(1, length + rem):
                if rem == 1:
                    if grid[row][col - bump] != '#':
                        (stack.append(((row, max(col + bump - 2, 1)), min(new_length, length), -dir, dir, path + [pos_to_coord(col - 1 + bump)])), done.add((row, col - bump + 1)))
                    if grid[row][col + bump - 2] != '#':
                        (stack.append(((row, max(col - bump + 2, 1)), min(new_length, length), -dir, dir, path + [pos_to_coord(col + 1 - bump)])), done.add((row, col + bump - 1)))
                if rem == 0:
                    if grid[row][col - bump] != '#':
                        (stack.append((position, min(new_length, length), -dir, dir, path)), done.add((row, col - bump + 1)))
                    if grid[row][col + bump - 2] != '#':
                        (stack.append((position, min(new_length, length), -dir, dir, path)), done.add((row, col + bump - 1)))
        for d_r, d_c in ((-1, 0), (0, -1), (1, 0), (0, 1), (0, 0)):
            new_row, new_col = (row + d_r, col + d_c)
            if 0 < new_row < len(grid) and 0 < new_col < start_len and (grid[row + d_r][col + d_c] != '#') and ((new_row, new_col) not in done):
                stack.append((position, length + 1, -(d_c * 2), dir, path))
    return []

