def get_adj_pos(i: int, j: int) -> list[int]:
    """
    gets the adjacency of (i, j) indices
    i -> row
    j -> col
    """
    for yi, xj in ((i + 1, j), (i - 1, j), (i, j + 1), (i, j - 1)):
        yield (yi, xj)

def is_valid_index(grid: list, str, i: int, j: int) -> bool:
