def valid_moves(grid: list[str], current: tuple[int, int]) -> list[tuple[int, int]]:
    rows = max((i for i, _ in current))
    rows -= 1
    cols = max((i for _, i in current))
    cols -= 1
    moves = []
    for cell in [(current[0] + rows, current[1]), (current[0] - rows, current[1]), (current[0], current[1] + cols), (current[0], current[1] - cols)]:
        if cell[0] < 0 or cell[1] < 0:
            continue
        if cell_value(grid, cell) == '.':
            moves.append(cell)
    return moves

