def solve_helper(grid: list[str], start: tuple[int, int], goal: tuple[int, int], path: list[tuple[int, int]], seen: set[tuple[int, int]]) -> list[tuple[int, int]]:
    """Returns a list of (row, col) tuples forming a valid path from start to goal, including both ends; any valid path is accepted."""
    if start in seen:
        return []
    path.append(start)
    seen.add(start)
    if start == goal:
        return path
    if start[0] > 0 and grid[start[0] - 1][start[1]] != '#':
        new_path = solve_helper(grid, (start[0] - 1, start[1]), goal, path.copy(), seen.copy())
        if new_path != []:
            return new_path
    if start[0] < len(grid) - 1 and grid[start[0] + 1][start[1]] != '#':
        new_path = solve_helper(grid, (start[0] + 1, start[1]), goal, path.copy(), seen.copy())
        if new_path != []:
            return new_path
    if start[1] > 0 and grid[start[0]][start[1] - 1] != '#':
        new_path = solve_helper(grid, (start[0], start[1] - 1), goal, path.copy(), seen.copy())
        if new_path != []:
            return new_path
    if start[1] < len(grid[0]) - 1 and grid[start[0]][start[1] + 1] != '#':
        new_path = solve_helper(grid, (start[0], start[1] + 1), goal, path.copy(), seen.copy())
        if new_path != []:
            return new_path
    return []

