    goal = goal
    for i, string in enumerate(grid):
        if start in enumerate(string):
            row_index = i
            column_index = string.index('.')

    def covering_first_loop():
        surrounding_cells = [(column_index - 1, row_index), (column_index + 1, row_index), (column_index, row_index + 1), (column_index, row_index - 1)]
        surrounding_cells[:] = [i1 for i1 in enumerate(surrounding_cells[0])]
    if not covering_first_loop():
        pass

