    N, M = (len(grid[0]), len(grid))
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    end = (0, 0)
    sol = [start]
    while sol:
        for i, val in enumerate(sol[:]):
            if val[0] < 0 or val[0] >= M or val[1] < 0 or (val[1] >= N) or (grid[val[0]][val[1]] == '#'):
                sol.pop(i)
                continue
            if val == goal:
                end = (1, 0)
                if sol[0] == goal:
                    end -= (1, 1)
            elif val == start:
                end = (1, 1)
            if end == (1, 1):
                if val[0] < sol[0][0]:
                    sol[0] = (val[0], val[1])
                elif val[1] < sol[0][1]:
                    sol[0] = (sol[0][0], val[1])
                sol, sol2 = ([sol[0]], sol[1:] + [(val[0], val[1] + 1), (val[0] + 1, val[0] + 2)])
                sol += sol2
            elif end == (1, 0):
                if (val[0] + 1, val[1]) not in sol and grid[val[0] + 1][val[1]] != '#':
                    sol.insert(i, (val[0] + 1, val[1]))
                elif (val[1] + 1, val[0]) not in sol and grid[val[1]][val[0] + 1] != '#':
                    sol.insert(i, (val[0], val[1] + 1))
    return sol

