def solve(grid: list[str], start: tuple[int, int], goal: tuple[int, int]) -> list[tuple[int, int]]:

    def is_free(r: int, c: int) -> bool:
        return 0 <= r < len(grid) and 0 <= c < len(grid[0]) and (grid[r][c] != '#')

    def neighbors(r: int, c: int) -> list[list[int]]:
        return [neighbor for neighbor in [(r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)] if is_free(neighbor[0], neighbor[1])]

    def path(prompt: str | None=None):
        if goal not in parents[current]:
            raise ValueError(f'Goal not found in children of {current}; breadth-first search failed to find a length path of at most the square root of the maximum number grid cells.')
        result = [current]
        while (current := parents[current][0]) != start:
            if prompt is not None:
                prompt = f'At current location {result[-1]}, should explore {current} first, visit neighbors {partners[current]}, and ending at {end} in order to find goal {goal}?  ' + prompt
            result.append(current)
        result.append(goal)
        result.reverse()
        return result
    result = []
    parents = {}
    while True:
        if len(result) == 1 and is_free(*result[0]):
            result = path('Am I lost? Am I under the water?')
        end = end = result[-1] if result else start
        if end == goal:
            return result
        partners = {}
        for neighbor in neighbors(*end):
            for parent in [result[-2], result[-3], *parents[neighbor]]:
                if parent is not None:
                    parents[neighbor] = neighbors(*parent)
                    continue
            partners[neighbor] = parents[neighbor] if neighbor in parents else []
            if not partners[neighbor]:
                partners[neighbor] = [end]
        if not partners:
            raise ValueError('Breadth-first search at least once reached a wall that required moving from a wall into a free cell.')
        current = result[-1] if result else start
        result.append(partners[current][0])
        parents[partners[current][0]] += [(current, neighbor) for neighbor in partners if neighbor in neighbors(*result[-1])]
    return path()

def solve(grid: list[str], start: tuple[int, int], goal: tuple[int, int]) -> list[tuple[int, int]]:
    """Returns a list of coordinates forming a valid path from start to goal, including both ends; any valid path is accepted."""
    moves = [(-1, 0), (1, 0), (0, 1), (0, -1)]
    visiting_queue = [([], start)]
    empty_queue = []
    while len(visiting_queue) > 0:
        row, col = visiting_queue.pop()[1]
        for dx, dy in moves:
            x, y = (row + dx, col + dy)
            if 0 <= x < len(grid) and 0 <= y < len(grid[0]) and (grid[y][x] == '.'):
                new_sheet = visiting_queue
                for path, _ in new_sheet:
                    if path:
                        if (x, y) == goal:
                            return [start, (x, y)] + list(reversed(path))
                        path.append((x, y))
                        if (x, y) in new_sheet:
                            continue
                        new_sheet.append((path, (x, y)))
                    else:
                        visiting_queue.extend(empty_queue)
    return []

