    visited = {start}
    frontier = [[start]]
    while len(frontier) != 0:
        planned_rotes = frontier.pop()
        row, col = planned_rotes[-1]
        if (row, col) == goal:
            return planned_rotes
        next_planned_rotes = [planned_rotes]
        for r, c in {(row + 1, col), (row - 1, col), (row, col + 1), (row, col - 1)} - visited:
            if grid[r][c] != '#':
                visited.add((r, c))
                next_planned_rotes.append(planned_rotes + [r, c])
        frontier += next_planned_rotes
    return []

