def solve(grid: list[str], start: tuple[int, int], goal: tuple[int, int]) -> list[tuple[int, int]]:
    if grid == [] or len(grid[0]) == 0:
        return []
    overall_explored_grid = []
    while len(grid) * len(grid[0]) > len(overall_explored_grid):
        overall_explored_grid.append([None] * len(grid[0]))
    max_eligible_row = len(grid)
    max_eligible_col = len(grid[0])
    explored_grid = overall_explored_grid

    def spa(grid, start, explored_grid):
        stack_of_tuples = [start]
        while stack_of_tuples:
            top_of_stack = stack_of_tuples.pop(0)
            x = top_of_stack[0]
            y = top_of_stack[1]
            if x < max_eligible_row and x >= 0 and (y >= 0) and (y < max_eligible_col):
                current_tile = grid[x][y]
                explored_grid[x][y] = True
                if current_tile == '.':
                    stack_of_tuples.insert(0, (x - 1, y))
                    stack_of_tuples.insert(0, (x + 1, y))
                    stack_of_tuples.insert(0, (x, y - 1))
                    stack_of_tuples.insert(0, (x, y + 1))
                if current_tile == '#':
                    pass
        return explored_grid
    explored_grid = spa(grid, start, explored_grid)
    path = []
    i = start[0]
    j = start[1]
    while i != goal[0] or j != goal[1]:
        finish_pass = False
        if i == goal[0] and j == goal[1]:
            break
        if i - 1 >= 0:
            is_checked = explored_grid[i - 1][j]
            is_cell_free = grid[i - 1][j] == '.'
            is_diagonal_unoccupied = True
            if i < len(grid) - 1 and j < len(grid[i]) - 1:
                if grid[i + 1][j + 1] == '#':
                    is_diagonal_unoccupied = False
            if is_checked and is_cell_free and is_diagonal_unoccupied:
                i -= 1
                path.append((i, j))
                finish_pass = True
                explored_grid = spa(grid, (i, j), explored_grid)
        if not finish_pass:
            if i + 1 < len(grid):
                is_checked = explored_grid[i + 1][j]
                is_cell_free = grid[i + 1][j] == '.'
                is_diagonal_unoccupied = True
                if i < len(grid) - 1 and j < len(grid[i]) - 1:
                    if grid[i + 1][j + 1] == '#':
                        is_diagonal_unoccupied = False
                if is_checked and is_cell_free and is_diagonal_unoccupied:
                    i += 1
                    path.append((i, j))
                    finish_pass = True
                    explored_grid = spa(grid, (i, j), explored_grid)
        if not finish_pass:
            if j - 1 >= 0:
                is_checked = explored_grid[i][j - 1]
                is_cell_free = grid[i][j - 1] == '.'
                is_diagonal_unoccupied = True
                if i < len(grid) - 1 and j < len(grid[i]) - 1:
                    if grid[i + 1][j - 1] == '#':
                        is_diagonal_unoccupied = False
                if is_checked and is_cell_free and is_diagonal_unoccupied:
                    j -= 1
                    path.append((i, j))
                    finish_pass = True
                    explored_grid = spa(grid, (i, j), explored_grid)
        if not finish_pass:
            if j + 1 < len(grid[0]):
                is_checked = explored_grid[i][j + 1]
                is_cell_free = grid[i][j + 1] == '.'
                is_diagonal_unoccupied = True
                if i < len(grid) - 1 and j < len(grid[i]) - 1:
                    if grid[i + 1][j + 1] == '#':
                        is_diagonal_unoccupied = False
                if is_checked and is_cell_free and is_diagonal_unoccupied:
                    j += 1
                    path.append((i, j))
                    finish_pass = True
                    explored_grid = spa(grid, (i, j), explored_grid)
        if not finish_pass:
            return []
    return path

def solve(grid: list[str], start: tuple[int, int], goal: tuple[int, int]) -> list[tuple[int, int]]:

    def valid_coords(x, y):
        return 0 <= x < len(grid) and 0 <= y < len(grid[0])
    matrix = [[0] * len(grid[0]) for _ in range(len(grid))]
    queue = [start]
    while queue:
        row, col = queue.pop()
        if matrix[row][col]:
            continue
        if grid[row][col] == '#':
            continue
        if row == goal[0] and col == goal[1]:
            break
        matrix[row][col] = 1
        for row_move, col_move in ((row - 1, col), (row + 1, col), (row, col - 1), (row, col + 1)):
            if valid_coords(row_move, col_move) and (not matrix[row_move][col_move]):
                queue.append((row_move, col_move))
    path = []
    if goal not in queue:
        return path
    row, col = goal
    while (row, col) != start:
        path.append((row, col))
        for row_move, col_move in ((row - 1, col), (row + 1, col), (row, col - 1), (row, col + 1)):
            if valid_coords(row_move, col_move) and matrix[row_move][col_move] == 1:
                row, col = (row_move, col_move)
                break
    return path[::-1]

