def neighbor(grid: list[str], visited: list[str], g: int, h: int, movestypes=None) -> list:
    length = len(grid)
    if movestypes is not None:
        movestypes = [element for element in movestypes][1:]
    if len(movestypes) != 0:
        mx, my = (movestypes[0][0], movestypes[0][1])
        nx = g + mx
        ny = h + my
    else:
        nx = g + movestypes[0][0]
        ny = h + movestypes[0][1]
    if ny < length and nx < length and (nx >= 0) and (ny >= 0):
        if grid[nx][ny] == '#' or (nx, ny) in visited:
            return neighbor(grid, visited, nx, ny, movestypes)
        else:
            visited.append((nx, ny))
            path = neighbor(grid, visited, nx, ny, movestypes)
            if len(path[0]) > 0:
                return path
            else:
                path = [[(nx, ny)]]
                for j in range(1, 4):
                    mx = movestypes[j][0]
                    my = movestypes[j][1]
                    nx = g + mx
                    ny = h + my
                    if grid[nx][ny] == '#' or (nx, ny) in visited:
                        return path
                    else:
                        visited.append((nx, ny))
                        path.append([(nx, ny)])
                return path

