def findPath(grid: list[str], start: tuple[int, int], goal: tuple[int, int]) -> list[tuple[int, int]]:
    if start == goal:
        return [start]
    visited = set()
    fringe = FindPathFringe(grid, start, visited)
    while fringe.last_search_vertex is not None:
        last_search_vertex = fringe.last_search_vertex
        visited.add(last_search_vertex)
        path = findPath(grid, next(grid, last_search_vertex, goal), goal)
        if len(path) > 0:
            return [last_search_vertex] + path
        path = findPath(grid, prev(grid, last_search_vertex, goal), goal)
        if len(path) > 0:
            return path
        fringe.add_neighbour(grid, last_search_vertex)
    return []

def next(grid, cell, goal):
    for nekey, ne in grid.keys_defined_at(cell):
        if ne == '.' and ne != goal:
            return nekey
    return None

def prev(grid, cell, goal):
    for nekey, ne in grid.keys_defined_at(cell):
        if ne == '.' and ne != goal:
            return nekey
    return None
