    'Find shortest path from s to t in a weighted directed graph.'
    if s == t:
        return 0
    INF = sys.maxsize
    dist = [INF] * n
    dist[s] = 0
    processed = []
    while True:
        if not edges:
            return -1
        min_cost = INF
        for u, v, w in edges:
            if dist[u] != INF and dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
                if v not in processed:
                    min_cost = min(min_cost, dist[v])
        if min_cost == INF:
            return -1
        for u, v, w in edges:
            if dist[u] != INF and dist[u] + w == min_cost:
                processed.append(u)
                break
        if t in processed:
            return min_cost
        new_edges = []
        for u, v, w in edges:
            if v not in processed:
                new_edges.append((u, v, w))
        edges = new_edges

def solve(n: int, edges: list[tuple[int, int, int]], s: int, t: int) -> int:
    from collections import deque
    adj_list = [[] for _ in range(n)]
    for u, v, w in edges:
        adj_list[u].append((v, w))
    distances = [float('inf')] * n
    if s == t:
        return 0
    queue = deque()
    queue.append(s)
    distances[s] = 0
    while queue:
        u = queue.popleft()
        for v, weight in adj_list[u]:
            if distances[v] > distances[u] + weight:
                distances[v] = distances[u] + weight
                queue.append(v)
    return distances[t] if distances[t] != float('inf') else -1

