class Dijkstra:

    def __init__(self, adjacent: dict[int, list[tuple[int, int]]]):
        self.distance = {k: float('INF') for k in adjacent.keys()}
        self.distance[s] = 0
        self.queue = [(0, s)]
        self.adjacent = adjacent
        self.nodes = {k: bool(v) for k, v in self.distance.items()}

    def process_node(self) -> int:
        u = self.nodes[min(self.nodes, key=lambda k: self.distance[k])]
        del self.nodes[u]
        if self.distance[u] == float('INF'):
            return -1
        for v in self.adjacent[u]:
            self.distance[v] = min(self.distance[v], self.distance[u] + self.adjacent[u][v])
        return int(self.distance[u])

    def process_queue(self) -> int:
        while self.queue:
            u = self.nodes[min(self.nodes, key=lambda k: self.distance[k])]
            del self.nodes[u]
            if self.distance[u] == float('INF'):
                return -1
            for v in self.adjacent[u]:
                self.queue.append((self.distance[u] + self.adjacent[u][v], v))
        return int(self.distance[t])

