def shorts(start: int, target: int, edges: list[tuple[int, int, int]]):
    next, length = BFS(start, edges)
    solution = [start]
    try:
        w = while_visiting(next, target, solution)
        length += w
    except KeyError:
        return (0, length)
    return (next[target], length)

def while_visiting(next: dict, target: int, solution: list[int]):
    while target != solution[-1] and target in next:
        solution.append(next[target])
        target = next[target]
    return next[target]

def BFS(start: int, edges: list) -> tuple | int:
    front: list[int] = [start]
    next: dict[int, int] = {start: 0}
    d: dict[int, int] = {v: 0 for v in range(len(edges[0]) - 1)}
    d[start] = 1
    solved = False
    length, target = (1, None)
    while solved != True:
        for p in front:
            if p == target:
                solved = True
                break
            for child, parent, w in edges:
                if child == p and parent not in d or (child == p and next.get(parent) != None and (d.get(child) * d.get(parent) > d.get(child) + w)):
                    if child == p and (not next.get(parent) != None or d.get(child) + w < d.get(child) * d.get(parent)):
                        next[parent] = child
                        front.append(child)
                        d[child] = d[p] * d[parent] / (d[p] + w)
        front.pop(0)
    return (next, length)
