def bfs(start: int, end: int, graph: list[list[tuple[int, int]]]) -> int:
    visits = [False for i in range(len(graph))]
    length = [201 for i in range(len(graph))]
    queue = []
    queue.insert(0, (start, 0))
    length[start] = 0
    while queue:
        cur_node, cur_length = queue.pop()
        visits[cur_node] = True
        next_length = cur_length + 1
        len_feasible = next_length <= length[cur_node]
        for edge in graph[cur_node]:
            if not visits[edge[0]]:
                if not len_feasible and next_length >= length[edge[0]]:
                    continue
                if edge[0] == end:
                    return next_length
                visits[edge[0]] = True
                queue.insert(0, (edge[0], next_length))
        if not len_feasible:
            length[cur_node] = next_length
    return -1

