        new_source_priority: list[tuple[int, int]] = []
        new_source_dist: dict[int, int] = {}
        new_shortest_paths: dict[int, list[list[int]]] = {}
        for weight, source in source_priority:
            edges_to = adjacency[source]
            edge_weights = set()
            for node, edge_weight in edges_to:
                if node in source_dist:
                    if source_dist[node] < source_dist[source] + edge_weight:
                        new_source_priority.append((source_dist[node], node))
                    edge_weights.add(source_dist[node])
