    """Function returning a list of tuples on a path starting at start.
    """

    def in_grid(cell: tuple[int, int]) -> bool:
        return 0 <= cell[0] < len(grid) and 0 <= cell[1] < len(grid[0])

    def valid(grid: list[str], cell: tuple[int, int]) -> bool:
        """Valid return True iff trying to move to cell is a valid move.

        Args :
        cell : the cell to move to

        Returns :
        True if moving to cell is a valid move, False otherwise
        """
        valid_chars = ('#', '.', '+')
        return grid[cell[0]][cell[1]] in valid_chars

    def search(grid, start, goal):
        paths = [[start]]
        screen = []
        while len(paths) != 0:
            new_paths = []
            for path in paths:
                current = path[-1]
                if current == goal:
                    return path
                for d in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                    next = (current[0] + d[0], current[1] + d[1])
                    if valid(grid, current) and in_grid(next) and (grid[next[0]][next[1]] != '#') and (next not in screen):
                        next_path = path[:]
                        next_path.append(next)
                        new_paths.append(next_path)
            paths = new_paths
        return []
    grid = [list(row) for row in grid]
    path = search(grid, start, goal)
    if path:
        path = [(index[0], index[1]) for index in path]
    return path

