def solve(n: int, edges: list[tuple[int, int, int]], s: int, t: int) -> int:
    import heapq
    adj = {i: [] for i in range(n)}
    for u, v, w in edges:
        adj[u].append((w, v))

    def dijkstra(adj, s):
        visited = set()
        q = [(0, s)]
        while q:
            dist, node = heapq.heappop(q)
            if node in visited:
                continue
            visited.add(node)
            yield dist
            for w, neigh in adj[node]:
                if neigh not in visited:
                    heapq.heappush(q, (dist + w, neigh))
    return next(dijkstra(adj, s), -1) if s != t else 0

