def solve(n: int, edges: list[tuple[int, int, int]], s: int, t: int) -> int:
    if s == t:
        return 0
    if not go_space(s, edges):
        return -1
    reach: dict[int, tuple[int]] = {s}
    dist: dict[int, int] = {s: 0}
    target_reached: bool = False
    max_dist: int = max([e[2] for e in edges])
    current_dist: int = 0
    while not target_reached:
        nextdist: dict[int, int] = {}
        for n in reach:
            for m in go_space(n, edges):
                nextdist[m] = dist[n] + edges[n, m][2]
        new_reach: dict[int, tuple[int]] = {}
        for n, d in nextdist.items():
            if n not in reach and d < current_dist + max_dist:
                if n == t:
                    target_reached = True
                    break
                new_reach[n] = d
        for k in new_reach.keys():
            dist[k] = new_reach[k]
        current_dist += 1
        reach = new_reach
    return dist[t]

def go_space(owner: int, maps: list[tuple[int, int, int]]) -> list[int]:
    to_move: list[int] = []
    for t in maps:
        if t[0] == owner:
            to_move += [t[1]]
    return to_move
