def alt_fun(distances: dict, edges: list[tuple[int, int, int]]) -> dict:
    """One relaxation iteration, return new distances"""
    new_distances: dict = {}
    for v in distances:
        new_distances[v] = distances[v]
    for [u, v, w] in edges:
        new_distances[v] = min(new_distances[v], distances[u] + w)
    return new_distances

