def solve(n: int, edges: list[tuple[int, int, int]], s: int, t: int) -> int:
    """
        Solve the shortest path problem using the Floyd-Warshall algorithm.
    """
    constraint_reach = [[0] * n for _ in range(n)]
    unconstrained_reach = [[float('inf')] * n for _ in range(n)]
    uncertain_reach = [[False] * n for _ in range(n)]
    for u, v, w in edges:
        constraint_reach[u][v] = w
        unconstrained_reach[u][v] = w
        uncertain_reach[u][v] = True
    for k in range(n):
        for i in range(n):
            for j in range(n):
                if constraint_reach[i][k] != 0 and constraint_reach[k][j] != 0:
                    constraint_reach[i][j] = min(constraint_reach[i][j], constraint_reach[i][k] + constraint_reach[k][j])
                    unconstrained_reach[i][j] = min(unconstrained_reach[i][j], unconstrained_reach[i][k] + unconstrained_reach[k][j])
                    uncertain_reach[i][j] = True
    if t not in range(n):
        raise ValueError('Node t out of bounds')
    if uncertain_reach[s][t]:
        longest_shorter_path = unconstrained_reach[s][t] + 1 if unconstrained_reach[s][t] != float('inf') and unconstrained_reach[s][t] > constraint_reach[s][t] else unconstrained_reach[s][t]
    elif s not in range(n):
        raise ValueError('Node s out of bounds')
    elif unconstrained_reach[s][t] < constraint_reach[s][t]:
        longest_shorter_path = unconstrained_reach[s][t]
    else:
        longest_shorter_path = unconstrained_reach[s][t] - 1
    return longest_shorter_path if longest_shorter_path != float('inf') else -1

